import heapq


def dependency_solver(data, order, maximize):
    packages = data["packages"]
    names = sorted(packages, reverse=(order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best = None
    best_result = None

    def search(chosen, edges, pending):
        nonlocal best, best_result
        if not pending:
            # Each selected package was reached through a root or an active
            # dependency; reject cycles, including self-loops.
            done, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in done:
                    return True
                active.add(name)
                for other in edges.get(name, ()):
                    if not visit(other):
                        return False
                active.remove(name)
                done.add(name)
                return True

            if not all(visit(name) for name in chosen):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if best is None or (vector > best if maximize else vector < best):
                best = vector
                best_result = {"versions": dict(chosen)}
            return

        # Consolidate constraints for each package. Pending entries are
        # (package, lower bound, upper bound).
        constraints = {}
        for name, low, high in pending:
            if name in constraints:
                old_low, old_high = constraints[name]
                constraints[name] = (max(low, old_low), min(high, old_high))
            else:
                constraints[name] = (low, high)
        for name, (low, high) in constraints.items():
            if name in chosen and not low <= chosen[name] <= high:
                return

        todo = [name for name in constraints if name not in chosen]
        if not todo:
            search(chosen, edges, [])
            return
        name = min(todo, key=lambda n: names.index(n))
        low, high = constraints[name]
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        rows.sort(key=lambda row: row["version"], reverse=maximize)
        for row in rows:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_edges = {key: list(value) for key, value in edges.items()}
            deps = [dep for dep in row.get("deps", [])
                    if not dep.get("feature") or dep["feature"] in features]
            next_edges[name] = [dep["name"] for dep in deps]
            next_pending = [(pkg, lo, hi) for pkg, (lo, hi) in constraints.items()
                            if pkg != name and pkg not in next_chosen]
            next_pending.extend((dep["name"], dep["min"], dep["max"])
                                for dep in deps)
            search(next_chosen, next_edges, next_pending)

    roots = [(name, bounds[0], bounds[1])
             for name, bounds in data["roots"].items()]
    search({}, {}, roots)
    return best_result if best_result is not None else {"error": "unsatisfiable"}


def build_dependency(order, maximize):
    return lambda data: dependency_solver(data, order, maximize)


def solve_ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (sequence, event.get("revision", 0), pos)
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        return (n + d // 2) // d if mode == "half_up" else n // d

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def solve_quota(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    candidates = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    for selection in combinations(candidates, k):
        ids = {job["id"] for job in selection}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in selection:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(selection, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in selection)
        selected_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and selected_ids < best_ids)):
            best_value, best_ids = value, selected_ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def solve_routes(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1

    def visit_mask(node):
        return sum(1 << i for i, required_node in enumerate(required)
                   if node == required_node)

    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial = (source, visit_mask(source), data["coupons"])
    start = data["start"]
    distances = {(initial): start}
    queue = [(start, source, initial[1], initial[2])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, next_remaining in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | visit_mask(next_node)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask,
                                           next_remaining))
    return {"arrival": None}


